    "treesummary": true
  }
]

{
  "path": {
    "type": "TEXT",
    "hint": "Full path of the file or link: index name first, then the path inside the index (e.g. myindex/dir/file.txt). Ordinary TEXT: filter with path LIKE 'myindex/dir/%', GROUP BY, etc. In aggregate_sql_query, to use path in partial_sql or final_sql, carry it through per_directory_shape and partial_shape."
  },
  "dirpath": {
    "type": "TEXT",
    "hint": "Full path of the directory containing the file or link (e.g. myindex/dir). Filter with dirpath LIKE 'myindex/dir/%'."
  },
  "dname": {
    "type": "TEXT",
    "hint": "Base name of the containing directory only, not a path."
  },
  "dmode": {
    "type": "INT64",
    "hint": "Directory's st_mode as INT64 (decimal). Same bitmask rules as mode on file rows."
  },
  "dnlink": {
    "type": "INT64",
    "hint": "directory unix number of links"
  },
  "duid": {
    "type": "INT64",
    "hint": "directory unix uid"
  },
  "dgid": {
    "type": "INT64",
    "hint": "directory unix gid"
  },
  "dsize": {
    "type": "INT64",
    "hint": "Directory row metadata size in bytes (the directory inode), not subtree total (see dtotsize/totsize)."
  },
  "dblksize": {
    "type": "INT64",
    "hint": "directory unix blksize for file"
  },
  "dblocks": {
    "type": "INT64",
    "hint": "directory unix number of blocks"
  },
  "datime": {
    "type": "INT64",
    "hint": "Directory unix access time: seconds since epoch (INT64). For relative windows, compute cutoffs in SQL from the current time you were given, e.g. atime < <now_epoch> - 30 * 86400; do not hand-compute epochs."
  },
  "dmtime": {
    "type": "INT64",
    "hint": "Directory unix modification time: seconds since epoch (INT64). For relative windows, compute cutoffs in SQL from the current time you were given, e.g. mtime < <now_epoch> - 30 * 86400; do not hand-compute epochs. In per_directory_sql, agecat(mtime) uses GUFI age bands relative to wall clock."
  },
  "dctime": {
    "type": "INT64",
    "hint": "Directory unix status-change time: seconds since epoch (INT64). For relative windows, compute cutoffs in SQL from the current time you were given; do not hand-compute epochs."
  },
  "dlinkname": {
    "type": "TEXT",
    "hint": "directory unix string for link name"
  },
  "dtotfiles": {
    "type": "INT64",
    "hint": "directory number files"
  },
  "dtotlinks": {
    "type": "INT64",
    "hint": "directory summed links"
  },
  "dminuid": {
    "type": "INT64",
    "hint": "directory min uid"
  },
  "dmaxuid": {
    "type": "INT64",
    "hint": "directory max uid"
  },
  "dmingid": {
    "type": "INT64",
    "hint": "directory min gid"
  },
  "dmaxgid": {
    "type": "INT64",
    "hint": "directory max gid"
  },
  "dminsize": {
    "type": "INT64",
    "hint": "directory min size"
  },
  "dmaxsize": {
    "type": "INT64",
    "hint": "directory max size"
  },
  "dtotzero": {
    "type": "INT64",
    "hint": "directory number of zero-size files"
  },
  "dtotltk": {
    "type": "INT64",
    "hint": "directory number <= 1024"
  },
  "dtotmtk": {
    "type": "INT64",
    "hint": "directory number > 1024"
  },
  "totltm": {
    "type": "INT64",
    "hint": "number <= 1048576"
  },
  "dtotmtm": {
    "type": "INT64",
    "hint": "directory number > 1048576"
  },
  "dtotmtg": {
    "type": "INT64",
    "hint": "directory number <= 1073741824"
  },
  "dtotmtt": {
    "type": "INT64",
    "hint": "directory number > 1073741824"
  },
  "dtotsize": {
    "type": "INT64",
    "hint": "directory summed size"
  },
  "dminctime": {
    "type": "INT64",
    "hint": "directory min ctime"
  },
  "dmaxctime": {
    "type": "INT64",
    "hint": "directory max ctime"
  },
  "dtotctime": {
    "type": "INT64",
    "hint": "directory summed ctime"
  },
  "dminmtime": {
    "type": "INT64",
    "hint": "directory min mtime"
  },
  "dmaxmtime": {
    "type": "INT64",
    "hint": "directory max mtime"
  },
  "dtotmtime": {
    "type": "INT64",
    "hint": "directory summed mtime"
  },
  "dminatime": {
    "type": "INT64",
    "hint": "directory min atime"
  },
  "dmaxatime": {
    "type": "INT64",
    "hint": "directory max atime"
  },
  "dtotatime": {
    "type": "INT64",
    "hint": "directory summed atime"
  },
  "dminblocks": {
    "type": "INT64",
    "hint": "directory min blocks"
  },
  "dmaxblocks": {
    "type": "INT64",
    "hint": "directory max blocks"
  },
  "dtotblocks": {
    "type": "INT16",
    "hint": "directory summed blocks"
  },
  "dtotxattr": {
    "type": "INT64",
    "hint": "directory number of files/links with xattrs present"
  },
  "ddepth": {
    "type": "INT64",
    "hint": "directory depth (number of slashes in path)"
  },
  "dmincrtime": {
    "type": "INT64",
    "hint": "directory min create time"
  },
  "dmaxcrtime": {
    "type": "INT64",
    "hint": "directory max create time"
  },
  "dtotcrtime": {
    "type": "INT64",
    "hint": "directory summed create time"
  },
  "atroot": {
    "type": "INT64",
    "hint": "at index root"
  },
  "name": {
    "type": "TEXT",
    "hint": "Base name of the file or link only, not a full path (use path). In per_directory_sql, ext(name) returns GUFI's extension string for the name."
  },
  "type": {
    "type": "TEXT",
    "hint": "Entry type: 'f' regular file, 'l' symlink. Directory rows are not here; use vrsummary (type 'd') for per-directory metadata and totals."
  },
  "inode": {
    "type": "TEXT",
    "hint": "inode number from source system"
  },
  "mode": {
    "type": "INT64",
    "hint": "Full Unix st_mode as INT64 in decimal (not octal literals in SQL). Filter with integer bitmasks, e.g. mode & 1024 for setgid, mode & 73 for any execute bit."
  },
  "nlink": {
    "type": "INT64",
    "hint": "unix number of links"
  },
  "uid": {
    "type": "INT64",
    "hint": "unix uid"
  },
  "gid": {
    "type": "INT64",
    "hint": "unix gid"
  },
  "size": {
    "type": "INT64",
    "hint": "Logical size in bytes. In aggregate_sql_query, bytecat(size) in per_directory_sql uses GUFI's size categories."
  },
  "blksize": {
    "type": "INT64",
    "hint": "unix blksize for file"
  },
  "blocks": {
    "type": "INT64",
    "hint": "unix number of blocks"
  },
  "atime": {
    "type": "INT64",
    "hint": "Unix access time: seconds since epoch (INT64). For relative windows, compute cutoffs in SQL from the current time you were given, e.g. atime < <now_epoch> - 30 * 86400; do not hand-compute epochs."
  },
  "mtime": {
    "type": "INT64",
    "hint": "Unix modification time: seconds since epoch (INT64). For relative windows, compute cutoffs in SQL from the current time you were given, e.g. mtime < <now_epoch> - 30 * 86400; do not hand-compute epochs. In per_directory_sql, agecat(mtime) uses GUFI age bands relative to wall clock."
  },
  "ctime": {
    "type": "INT64",
    "hint": "Unix status-change time: seconds since epoch (INT64). For relative windows, compute cutoffs in SQL from the current time you were given; do not hand-compute epochs."
  },
  "linkname": {
    "type": "TEXT",
    "hint": "unix string for link name"
  },
  "xattr_names": {
    "type": "BLOB",
    "hint": "concatenation of all extended attributes"
  },
  "crtime": {
    "type": "INT64",
    "hint": "create time epoch (some file systems provide)"
  },
  "ossint1": {
    "type": "INT64",
    "hint": "storage system specific integer"
  },
  "ossint2": {
    "type": "INT64",
    "hint": "storage system specific integer"
  },
  "ossint3": {
    "type": "INT64",
    "hint": "storage system specific integer"
  },
  "ossint4": {
    "type": "INT64",
    "hint": "storage system specific integer"
  },
  "osstext1": {
    "type": "TEXT",
    "hint": "storage system specific string"
  },
  "osstext2": {
    "type": "TEXT",
    "hint": "storage system specific string"
  },
  "pinode": {
    "type": "TEXT",
    "hint": "parent directory inode"
  },
  "ppinode": {
    "type": "TEXT",
    "hint": "parent parent directory inode"
  }
}
